module top_module(
  input clk, // added clock input
  input [n-1:0] r,
  output reg [m-1:0] d // changed output to reg type
);parameter n = 16; // number of received data bits
parameter m = 8; // number of decoded data bits
parameter k = 3; // number of bits in the convolutional code
parameter g = 3'b101; // generator polynomial for the convolutional code

reg [k-1:0] shift_reg; // shift register to store the last k received data bits
reg [1:0] state; // current state of the Viterbi algorithm
reg [m-1:0] decoded_bits; // decoded data bits

// Define the generator polynomial for the convolutional code
function [2:0] convolve;
  input [k-1:0] data;
  begin
    case(data)
      3'b000: convolve = 3'b000;
      3'b001: convolve = g;
      3'b010: convolve = 3'b010;
      3'b011: convolve = g ^ 3'b010;
      3'b100: convolve = 3'b100;
      3'b101: convolve = g ^ 3'b100;
      3'b110: convolve = 3'b110;
      3'b111: convolve = g ^ 3'b110;
    endcase
  end
endfunction

// Define the Viterbi algorithm
function [1:0] viterbi;
  input [k-1:0] data;
  begin
    case(data)
      3'b000: viterbi = 2'b00;
      3'b001: viterbi = 2'b01;
      3'b010: viterbi = 2'b10;
      3'b011: viterbi = 2'b11;
      3'b100: viterbi = 2'b11;
      3'b101: viterbi = 2'b10;
      3'b110: viterbi = 2'b01;
      3'b111: viterbi = 2'b00;
    endcase
  end
endfunction

// Connect the inputs to the decoder
always @ (posedge clk) begin
  shift_reg <= {r[n-1:k], shift_reg[k-1:1]}; // correct bits left-shifting
end

// Connect the decoder to the outputs
always @ (posedge clk) begin
  decoded_bits <= {decoded_bits[m-2:0], viterbi(convolve(shift_reg))};
  d <= decoded_bits; // removed slicing as d is already declared as reg
end

endmodule

