description:
Implement the Verilog module based on the following description.
Build a 4-bit register with an enable signal and asynchronous clear.
// (1) enable: Enables the register. Active high.
// (2) clear: Asynchronous clear of the register. Active high.
// (3) clk: Clock signal.
// (4) d: 4-bit data input of the register.
// (5) q: 4-bit output of the register.
module top_module(
	input clk,
	input enable,
	input clear,
	input [3:0] d,
	output reg [3:0] q);

code:
module top_module(
	input clk,
	input enable,
	input clear,
	input [3:0] d,
	output reg [3:0] q);always @(posedge clk or posedge clear) begin
	if (clear)
		q <= 4'b0000;
	else if (enable)
		q <= d;
end
endmodule

