description:
Design a PWM (Pulse Width Modulation) generator that outputs a square wave signal based on a defined duty cycle and frequency. The module takes a clock and a reset signal as inputs. It utilizes two counters: one for the overall PWM period and another to track the duty cycle. The output will be high for a duration determined by the duty cycle ratio, which is configurable (in this case, set to 3 out of 100,000). On each clock cycle, the counters are updated, and when the period counter reaches its maximum (100,000), both counters are reset, generating a PWM signal with a specified duty cycle.
module top_module(
   input clk,
   input reset,
   output reg pwm_out
  );

code:
module top_module(
   input clk,
   input reset,
   output reg pwm_out
  );// Define constants for duty cycle and frequency
  localparam DUTY_CYCLE = 3;
  localparam PERIOD = 100000;

  // Counter for PWM period
  reg [15:0] period_counter = 0;

  // Counter for PWM duty cycle
  reg [2:0] duty_cycle_counter = 0;

  always @ (posedge clk) begin
    if (reset == 0) begin
      // Reset the counters and the output
      period_counter <= 0;
      duty_cycle_counter <= 0;
      pwm_out <= 0;
    end
    else begin
      // Increment the period counter
      period_counter <= period_counter + 1;

      // If the period counter reaches PERIOD, reset it and the duty cycle counter
      if (period_counter == PERIOD) begin
        period_counter <= 0;
        duty_cycle_counter <= 0;
      end

      // Increment the duty cycle counter
      if (duty_cycle_counter < DUTY_CYCLE) begin
        duty_cycle_counter <= duty_cycle_counter + 1;
      end
      else begin
        duty_cycle_counter <= 0;
      end

      // Set the output based on the duty cycle counter
      if (duty_cycle_counter == 0) begin
        pwm_out <= 0;
      end
      else begin
        pwm_out <= 1;
      end
    end
  end

endmodule

