description:
Design a debouncing circuit for a push button (PB) input, which processes the button state changes to eliminate false triggering due to mechanical bounce. The circuit uses a clock signal (clk) to sample the button state and only updates the output state (PB_state) after a stable condition is met, with a counter (PB_cnt) used to determine how long the button state has been steady before confirming the change. When the button is pressed or released (PB_changed), the counter begins, and when the maximum count is reached, the output state is updated to reflect the stable button state.
module top_module(
    input clk,
    input PB,
    output reg PB_state
);

code:
module top_module(
    input clk,
    input PB,
    output reg PB_state
);reg init_state = 1'b0;
reg [11:0] PB_cnt = 12'd0;
wire PB_cnt_max = &PB_cnt;
wire PB_idle = (PB_cnt == 12'd0);
wire PB_changed = (PB != init_state);

always @(posedge clk)
if(PB_idle & PB_changed)
begin
    init_state = PB;
    PB_cnt = 12'd1;
end
else if(PB_cnt_max)
begin
    PB_state = init_state;
    PB_cnt = 12'd0;
end
else if(~PB_idle)
    PB_cnt = PB_cnt + 12'd1;

endmodule

