module sequence_detector (
    input clk,
    input in,
    input reset,
    output detected);parameter S0=0, S1=1, S2=2, S3=3, FOUND=4;
    reg [2:0] state;
    reg [2:0] next;

    always_comb begin
        case (state)
            S0: next = in ? S1 : S0;
            S1: next = in ? S2 : S0;
            S2: next = in ? S2 : S3;
            S3: next = in ? FOUND : S0;
            FOUND: next = in ? S1 : S0;
        endcase
    end

    always @(posedge clk) begin
        if (reset) state <= S0;
        else state <= next;
    end

    assign detected = (state == FOUND);

endmodule

