module wrap_around_counter (
	input clk,
	input reset,
	output reg [19:0] count);

	always @(posedge clk) begin
		if (reset)
			count <= 20'b00000000000000000000;
		else if (count == 20'b11111111111111111111)
			count <= 20'b00000000000000000000;
		else
			count <= count + 1;
	end

endmodule

