module modulo_counter (
	input clk,
	input reset,
	output reg [11:0] q);

always @(posedge clk) begin
	if (reset)
		q <= 12'b000000000000;
	else if (q == 999)
		q <= 12'b000000000000;
	else
		q <= q + 1;
end

endmodule

