description:
Design a reset synchronizer circuit that harmonizes an asynchronous active-low reset input (rst_n) with the clock signal (clk). The module generates a synchronous reset output (rst) that remains active for a specified duration (reset_period) following the assertion of rst_n. When rst_n is low, rst is asserted low as long as it remains low for the duration specified by the reset_period counter; thus providing a controlled reset pulse that ensures proper reset timing and synchronization within synchronous digital systems.
module top_module(
  input rst_n,
  input clk,
  output reg rst
);

code:
module top_module(
  input rst_n,
  input clk,
  output reg rst
);parameter reset_period = 10; // reset period in clock cycles

reg rst_sync;
reg [3:0] rst_counter;

always @(posedge clk) begin
  if (rst_n == 1'b0) begin
    rst_sync <= 1'b0;
    rst_counter <= 4'b0000;
  end else begin
    rst_sync <= rst_n;
    if (rst_counter < reset_period) begin
      rst_counter <= rst_counter + 1;
    end
  end
end

assign rst = rst_sync & (rst_counter < reset_period);

endmodule

